fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of rows and columns in the input
    let m = x.len();
    let n = x[0].len();

    // Prepare the transposed matrix with n rows,
    // each of which will have m elements.
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(n);
    for j in 0..n {
        let mut new_row: Vec<f32> = Vec::with_capacity(m);
        for i in 0..m {
            // The element at (j, i) in the transposed matrix
            // is the element at (i, j) in the original.
            new_row.push(x[i][j]);
        }
        result.push(new_row);
    }

    result
}

